// ==== perfil.js ====
/* static/js/modules/pasta_perfil/perfil.js
============================================
PERFIL — edição + preview + cores
============================================ */

(function() {
    'use strict';

    const form = document.getElementById('formPerfil');
    if (!form) return;

    const inputUsername = document.getElementById('username');
    const feedbackUsername = document.getElementById('usernameFeedback');
    const inputBio = document.getElementById('bio');
    const bioContador = document.getElementById('bioContador');
    const inputFoto = document.getElementById('foto');
    const fotoPreview = document.getElementById('fotoPreview');
    const btnSalvar = document.getElementById('btnSalvarPerfil');
    const btnAtualizarPreview = document.getElementById('btnAtualizarPreview');
    const previewIframe = document.getElementById('previewIframe');

    const inputCorPrimaria = document.getElementById('cor_primaria');
    const inputCorSecundaria = document.getElementById('cor_secundaria');
    const corPrimariaHex = document.getElementById('corPrimariaHex');
    const corSecundariaHex = document.getElementById('corSecundariaHex');

    // ==========================================================
    // USERNAME
    // ==========================================================
    let timeoutUsername = null;
    if (inputUsername) {
        inputUsername.addEventListener('input', function() {
            const username = this.value.trim().toLowerCase();
            this.value = username;
            clearTimeout(timeoutUsername);

            if (!username) {
                feedbackUsername.textContent = 'Letras minúsculas, números e _.';
                feedbackUsername.className = 'form-hint';
                return;
            }
            if (username.length < 3) {
                feedbackUsername.textContent = 'Mínimo 3 caracteres.';
                feedbackUsername.className = 'form-hint form-hint-erro';
                return;
            }
            if (!/^[a-z][a-z0-9_]*$/.test(username)) {
                feedbackUsername.textContent = 'Só minúsculas, números e _.';
                feedbackUsername.className = 'form-hint form-hint-erro';
                return;
            }

            feedbackUsername.textContent = 'Verificando...';
            feedbackUsername.className = 'form-hint form-hint-verificando';

            timeoutUsername = setTimeout(() => {
                fetch('/painel/perfil/verificar-username/' + encodeURIComponent(username))
                    .then(r => r.json())
                    .then(data => {
                        if (data.disponivel) {
                            feedbackUsername.textContent = '✅ Disponível!';
                            feedbackUsername.className = 'form-hint form-hint-ok';
                        } else {
                            feedbackUsername.textContent = '❌ ' + (data.message || 'Indisponível.');
                            feedbackUsername.className = 'form-hint form-hint-erro';
                        }
                    })
                    .catch(() => {
                        feedbackUsername.textContent = 'Erro ao verificar.';
                        feedbackUsername.className = 'form-hint form-hint-erro';
                    });
            }, 500);
        });
    }

    // ==========================================================
    // BIO
    // ==========================================================
    if (inputBio && bioContador) {
        const atualizar = () => { bioContador.textContent = inputBio.value.length; };
        inputBio.addEventListener('input', atualizar);
        atualizar();
    }

    // ==========================================================
    // FOTO
    // ==========================================================
    if (inputFoto && fotoPreview) {
        inputFoto.addEventListener('change', function() {
            const file = this.files[0];
            if (!file) return;

            if (file.size > 2 * 1024 * 1024) {
                Notificacao.erro('Imagem muito grande. Máximo 2MB.');
                this.value = '';
                return;
            }

            const reader = new FileReader();
            reader.onload = (e) => {
                fotoPreview.innerHTML = `<img src="${e.target.result}" alt="Preview">`;
            };
            reader.readAsDataURL(file);
        });
    }

    // ==========================================================
    // CORES
    // ==========================================================
    if (inputCorPrimaria) {
        inputCorPrimaria.addEventListener('input', function() {
            if (corPrimariaHex) corPrimariaHex.textContent = this.value;
        });
    }
    if (inputCorSecundaria) {
        inputCorSecundaria.addEventListener('input', function() {
            if (corSecundariaHex) corSecundariaHex.textContent = this.value;
        });
    }

    // Paletas prontas
    document.querySelectorAll('.paleta-btn').forEach(btn => {
        btn.addEventListener('click', function() {
            const prim = this.dataset.primaria;
            const sec = this.dataset.secundaria;

            if (inputCorPrimaria) {
                inputCorPrimaria.value = prim;
                if (corPrimariaHex) corPrimariaHex.textContent = prim;
            }
            if (inputCorSecundaria) {
                inputCorSecundaria.value = sec;
                if (corSecundariaHex) corSecundariaHex.textContent = sec;
            }
        });
    });

    // ==========================================================
    // ATUALIZAR PREVIEW
    // ==========================================================
    if (btnAtualizarPreview && previewIframe) {
        btnAtualizarPreview.addEventListener('click', function() {
            const src = previewIframe.src.split('?')[0];
            previewIframe.src = src + '?_=' + Date.now();
            Notificacao.sucesso('Preview atualizado!');
        });
    }

    // ==========================================================
    // SUBMIT
    // ==========================================================
    form.addEventListener('submit', function(ev) {
        ev.preventDefault();
        const formData = new FormData(form);

        if (btnSalvar) {
            btnSalvar.classList.add('loading');
            btnSalvar.disabled = true;
        }

        fetch('/painel/perfil/salvar', {
            method: 'POST',
            body: formData,
            headers: { 'X-Requested-With': 'XMLHttpRequest' }
        })
        .then(r => r.json().then(j => ({ ok: r.ok, data: j })))
        .then(({ ok, data }) => {
            if (!ok || !data.success) {
                Notificacao.erro(data.error || 'Erro ao salvar.');
                return;
            }
            Notificacao.sucesso(data.message || 'Perfil atualizado!');

            if (previewIframe && data.username) {
                setTimeout(() => {
                    const src = previewIframe.src.split('?')[0];
                    previewIframe.src = src + '?_=' + Date.now();
                }, 300);
            }
        })
        .catch(() => Notificacao.erro('Erro de conexão.'))
        .finally(() => {
            if (btnSalvar) {
                btnSalvar.classList.remove('loading');
                btnSalvar.disabled = false;
            }
        });
    });

    console.log('✅ Perfil carregado');

})();

